import {
  createOpenApiBadgeResolver,
  createOpenApiTagResolver,
  validate,
  DEFAULT_API_GROUP_NAME,
} from '@mintlify/common';
import type {
  DecoratedNavigation,
  DecoratedNavigationGroup,
  Navigation,
  NavigationGroup,
  DecoratedNavigationPage,
} from '@mintlify/models';
import { OpenAPI } from 'openapi-types';

import {
  getOpenApiDefinition,
  GenerateOpenApiPagesOptions,
  OpenApiPageGenerationResult,
  processOpenApiPath,
  processOpenApiWebhook,
} from './common.js';

export async function generateOpenApiPages(
  pathOrDocumentOrUrl: string | OpenAPI.Document | URL,
  opts?: GenerateOpenApiPagesOptions
): Promise<OpenApiPageGenerationResult<Navigation, DecoratedNavigation>> {
  const { document, isUrl } = await getOpenApiDefinition(
    pathOrDocumentOrUrl,
    opts?.localSchema,
    opts?.overlays
  );
  const { schema } = await validate(document);

  if (
    schema?.openapi?.startsWith('3.0.') &&
    (schema.paths === undefined || Object.keys(schema.paths).length === 0)
  ) {
    throw new Error('No paths defined.');
  } else if (
    (schema?.openapi?.startsWith('3.1.') || schema?.openapi?.startsWith('3.2.')) &&
    (schema.paths === undefined || Object.keys(schema.paths).length === 0) &&
    (schema.webhooks === undefined || Object.keys(schema.webhooks).length === 0)
  ) {
    throw new Error('No paths or webhooks defined.');
  }

  const generationOptions = {
    ...opts,
    resolveTags: createOpenApiTagResolver(schema as OpenAPI.Document),
    resolveBadge: createOpenApiBadgeResolver(schema as OpenAPI.Document),
  };

  const nav: Navigation = [];
  const decoratedNav: DecoratedNavigation = [];
  const writePromises: Promise<void>[] = [];
  const pagesAcc: Record<string, DecoratedNavigationPage> = {};

  if (schema?.paths) {
    Object.entries(schema.paths).forEach(([path, pathItemObject]) => {
      if (!pathItemObject || typeof pathItemObject !== 'object') {
        return;
      }
      processOpenApiPath<Navigation, DecoratedNavigation>(
        path,
        pathItemObject,
        schema as OpenAPI.Document,
        nav,
        decoratedNav,
        writePromises,
        pagesAcc,
        generationOptions,
        findNavGroup
      );
    });
  }

  if (schema?.webhooks) {
    Object.entries(schema.webhooks).forEach(([webhook, webhookObject]) => {
      if (!webhookObject || typeof webhookObject !== 'object') {
        return;
      }
      processOpenApiWebhook<Navigation, DecoratedNavigation>(
        webhook,
        webhookObject,
        schema as OpenAPI.Document,
        nav,
        decoratedNav,
        writePromises,
        pagesAcc,
        generationOptions,
        findNavGroup
      );
    });
  }

  await Promise.all(writePromises);

  return {
    nav,
    decoratedNav,
    spec: schema as OpenAPI.Document,
    pagesAcc,
    isUrl,
  };
}

const tagKeys = new WeakMap<object, string>();

const findNavGroup = <T extends NavigationGroup | DecoratedNavigationGroup>(
  nav: T['pages'][number][],
  groupName: string = DEFAULT_API_GROUP_NAME,
  tagKey?: string
): T['pages'][number][] => {
  const group = nav.find(
    (fileOrGroup) =>
      typeof fileOrGroup === 'object' &&
      'group' in fileOrGroup &&
      fileOrGroup.group === groupName &&
      (tagKey === undefined || tagKeys.get(fileOrGroup) === tagKey)
  ) as T | undefined;
  if (group === undefined) {
    const newGroup = {
      group: groupName,
      pages: [],
    };
    if (tagKey !== undefined) tagKeys.set(newGroup, tagKey);
    nav.push(newGroup);
    return newGroup.pages;
  } else {
    return group.pages;
  }
};
